    "publicNarration": {
      "beats": [
        {
          "text": "You find the village mill by its steady wooden clatter. Inside, pale light catches flour dust above a packing bench. Hobb, a broad-handed man in a dusty apron, sets down his tally stick and returns your greeting.",
          "requiresOperations": []
        },
        {
          "text": "“Crate-packing? Aye, there's a batch waiting.” He points to six open crates beside a stack of small flour sacks. “Two silver for the lot—about an hour's work. Check the sack ties, pack them snug, then nail the lids down. I'll pay when they're finished.”\n\nHe shifts a hammer out of the flour dust. “I'll show you the first one, if that suits.”",
          "requiresOperations": []
        }
      ],
      "visualDescription": null,
      "sceneLocale": {
        "label": "Village mill — packing room",
        "requiresOperations": []
      }
    },
    "genericOperations": [],
    "privatePatches": [],
    "publicBehavior": []
  }
}

